begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(13);
insert into public.accounts(id,slug,name,timezone) values('11600000-0000-4000-8000-000000000001','t10-read-test','T10','Asia/Shanghai');
insert into public.account_memberships(account_id,user_id,role) select '11600000-0000-4000-8000-000000000001',id,'owner' from auth.users order by id limit 1;
insert into public.account_blueprint_versions(id,account_id,version,policy,is_active) values('11600000-0000-4000-8000-000000000002','11600000-0000-4000-8000-000000000001',1,'{}',true);
insert into public.episodes(id,account_id,blueprint_version_id,title,is_test) values('11600000-0000-4000-8000-000000000003','11600000-0000-4000-8000-000000000001','11600000-0000-4000-8000-000000000002','T10',true);
insert into public.tasks(id,episode_id,task_type,status,input_snapshot,budget_limit_cents,max_attempts,provider,model,prompt_version) values('11600000-0000-4000-8000-000000000004','11600000-0000-4000-8000-000000000003','draft_brief','ready','{}',0,2,'codex','controlled','t10');
select set_config('request.jwt.claim.sub',(select user_id::text from public.account_memberships where account_id='11600000-0000-4000-8000-000000000001'),true);
create temporary table t10_initial as select public.read_episode_production('11600000-0000-4000-8000-000000000003') data;
select is((select data#>>'{sections,episode,title}' from t10_initial),'T10','aggregate preserves episode fields');
select is((select jsonb_array_length(data#>'{patches,tasks,rows}') from t10_initial),1,'initial task history included');
select is((select data#>'{sections,artifacts}' from t10_initial),'[]'::jsonb,'empty arrays preserve shape');
select is(public.read_episode_production('11600000-0000-4000-8000-000000000003',(select data->'hashes' from t10_initial))->'sections','{}'::jsonb,'unchanged sections not resent');
update public.tasks set status='failed' where id='11600000-0000-4000-8000-000000000004';
select is(public.read_episode_production('11600000-0000-4000-8000-000000000003',(select data->'hashes' from t10_initial))#>>'{patches,tasks,rows,0,status}','failed','task status delta returned');
select is(public.read_episode_production('11600000-0000-4000-8000-000000000003',(select data->'hashes' from t10_initial))->'sections','{}'::jsonb,'task update does not resend artifact or review history');
select is(public.read_episode_production('11600000-0000-4000-8000-000000000003',(select data->'hashes' from t10_initial))#>'{patches,tasks,rows}' @> '[{"id":"11600000-0000-4000-8000-000000000004"}]'::jsonb,true,'changed task row is included');
create temporary table t10_updated as select public.read_episode_production('11600000-0000-4000-8000-000000000003') data;
select is(public.read_episode_production('11600000-0000-4000-8000-000000000003',(select data->'hashes' from t10_updated))->'patches','{}'::jsonb,'unchanged task and run histories skipped');
delete from public.tasks where id='11600000-0000-4000-8000-000000000004';
select is(public.read_episode_production('11600000-0000-4000-8000-000000000003',(select data->'hashes' from t10_updated))#>'{patches,tasks,ids}','[]'::jsonb,'deleted tasks removed from incremental snapshot');
select set_config('t10.known',(public.read_episode_production('11600000-0000-4000-8000-000000000003')->'hashes')::text,true);
revoke select on public.artifacts from authenticated;
set local role authenticated;
select is(public.read_episode_production('11600000-0000-4000-8000-000000000003',current_setting('t10.known')::jsonb)->'sections','{}'::jsonb,'unchanged artifacts skipped even when table read is prohibited');
select ok(not has_table_privilege('authenticated','public.episode_read_revisions','update'),'browser cannot alter revision metadata');
reset role;
select set_config('request.jwt.claim.sub','11600000-0000-4000-8000-000000000099',true);
select is(public.read_episode_production('11600000-0000-4000-8000-000000000003'),null::jsonb,'other Owner receives no snapshot');
select ok(not has_function_privilege('anon','public.read_episode_production(uuid,jsonb)','execute'),'anonymous cannot invoke aggregate');
select * from finish();
rollback;
